"""
Evaluate the discretised action of an open trajectory. SPECIFICATION: path has shape (n + 1, 2) and eps is the spacing of the evolution parameter between consecutive rows. The action is the mass, which is one, divided by twice eps, times the sum over consecutive rows of the squared Euclidean distance between them, plus eps times the sum of the potential over all rows in which the FIRST and LAST rows each count one half and every interior row counts one. Return a single real number.

Discretising a continuous trajectory turns its action into a sum of spring terms between neighbouring replicas plus a quadrature of the potential along the chain. The end rows of an open chain carry half the potential weight, which is the trapezoidal rule and not a detail: it is exactly what makes the stationarity condition at each free end reproduce the physical condition there, so the ends settle where they should instead of drifting.

Returns
-------
float.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def path_action(path: "np.ndarray", eps: float, a: float, c: float, wy: float) -> float:
    """Evaluate the discretised action of an open trajectory. SPECIFICATION: path has shape (n + 1, 2) and eps is the spacing of the evolution parameter between consecutive rows. The action is the mass, which is one, divided by twice eps, times the sum over consecutive rows of the squared Euclidean distance between them, plus eps times the sum of the potential over all rows in which the FIRST and LAST rows each count one half and every interior row counts one. Return a single real number.

    Returns
    -------
    float.

    Raises
    ------
    ValueError: if path does not have shape (n + 1, 2) with n at least two, or if eps is not positive and finite.
    """
    return action  # placeholder

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np
import scipy.sparse as sp
import scipy.sparse.linalg as spla
from scipy.optimize import brentq


def _oracle_path_action(path: "np.ndarray", eps: float, a: float, c: float, wy: float) -> float:
    mass = 1.0
    X = np.atleast_2d(np.asarray(path, dtype=float))
    if X.ndim != 2 or X.shape[1] != 2 or X.shape[0] < 3:
        raise ValueError("path must have shape (n + 1, 2) with n >= 2")
    if not np.isfinite(eps) or eps <= 0.0:
        raise ValueError("eps must be positive and finite")
    V = _oracle_potential_and_derivatives(X, a, c, wy)[:, 0]
    S = (mass / (2.0 * eps)) * float(np.sum(np.diff(X, axis=0) ** 2))
    return float(S + eps * (0.5 * V[0] + float(V[1:-1].sum()) + 0.5 * V[-1]))

